public with sharing class AccountScoringJob implements Queueable {

    // Records handled by one execution (one SOQL query + one DML statement).
    @TestVisible private static final Integer BATCH_SIZE = 200;

    // Developer Edition / scratch orgs cap the queueable chain depth at 5
    // (the first job plus four chained jobs). A single chain therefore covers at
    // most 5 * 200 = 1,000 Ids. start() fans large lists out into independent
    // chains. A transaction may enqueue up to 50 jobs, so 50 chains * 1,000 Ids
    // covers 50,000 accounts.
    @TestVisible private static final Integer MAX_CHAIN_DEPTH = 5;
    @TestVisible private static final Integer MAX_JOBS_PER_TRANSACTION = 50;

    private static final Decimal HOT_THRESHOLD = 1000000;
    private static final Decimal WARM_THRESHOLD = 100000;

    private final List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = cleanIds(accountIds);
    }

    /**
     * Enqueues the scoring job(s) and returns the Id of the first job.
     * Null or empty input enqueues nothing and returns null.
     */
    public static Id start(List<Id> accountIds) {
        List<Id> ids = cleanIds(accountIds);
        if (ids.isEmpty()) {
            return null;
        }

        Integer chunkSize = BATCH_SIZE * MAX_CHAIN_DEPTH;
        Integer maxIdsCovered = chunkSize * MAX_JOBS_PER_TRANSACTION;
        if (ids.size() > maxIdsCovered) {
            // Beyond the designed volume: spread over the allowed number of jobs.
            chunkSize = (Integer) Math.ceil(Decimal.valueOf(ids.size()) / MAX_JOBS_PER_TRANSACTION);
        }

        Id firstJobId;
        Integer startIdx = 0;
        while (startIdx < ids.size()) {
            Integer endIdx = Math.min(startIdx + chunkSize, ids.size());
            List<Id> slice = new List<Id>();
            for (Integer i = startIdx; i < endIdx; i++) {
                slice.add(ids[i]);
            }
            Id jobId = System.enqueueJob(new AccountScoringJob(slice), chainOptions());
            if (firstJobId == null) {
                firstJobId = jobId;
            }
            startIdx = endIdx;
        }
        return firstJobId;
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer currentSize = Math.min(BATCH_SIZE, accountIds.size());
        Set<Id> currentIds = new Set<Id>();
        for (Integer i = 0; i < currentSize; i++) {
            currentIds.add(accountIds[i]);
        }

        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :currentIds
            WITH USER_MODE
        ];

        for (Account acc : accounts) {
            acc.Rating = calculateRating(acc.AnnualRevenue);
        }
        if (!accounts.isEmpty()) {
            update as user accounts;
        }

        if (accountIds.size() > currentSize) {
            List<Id> remaining = new List<Id>();
            for (Integer i = currentSize; i < accountIds.size(); i++) {
                remaining.add(accountIds[i]);
            }
            // Chaining is intentionally not skipped in tests.
            System.enqueueJob(new AccountScoringJob(remaining), chainOptions());
        }
    }

    // Explicit stack depth so that chained jobs are allowed to run (including in
    // Apex tests) up to the Developer Edition maximum of 5.
    private static AsyncOptions chainOptions() {
        AsyncOptions options = new AsyncOptions();
        options.MaximumQueueableStackDepth = MAX_CHAIN_DEPTH;
        return options;
    }

    @TestVisible
    private static String calculateRating(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= HOT_THRESHOLD) {
            return 'Hot';
        }
        if (annualRevenue != null && annualRevenue >= WARM_THRESHOLD) {
            return 'Warm';
        }
        return 'Cold';
    }

    private static List<Id> cleanIds(List<Id> source) {
        List<Id> result = new List<Id>();
        if (source != null) {
            for (Id i : source) {
                if (i != null) {
                    result.add(i);
                }
            }
        }
        return result;
    }
}
