/**
 * Nightly purge of FB_Integration_Log__c records.
 *  - Logs created more than 30 days ago are deleted.
 *  - Logs with Level__c = 'ERROR' are kept until they are more than 180 days old.
 *  - Logs with a blank Level__c are treated like any non-ERROR log.
 *
 * Only top-level classes can implement Database.Batchable, so this class is both
 * Schedulable and Batchable. Each scheduled run first deletes up to one
 * transaction's worth of expired logs synchronously. If that chunk was full
 * (so more expired logs may remain), it starts itself as a batch job to purge the rest.
 *
 * Runs in system mode on purpose: the purge must remove all expired logs
 * regardless of the sharing visibility of the user who scheduled the job.
 */
public without sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    public static final String JOB_NAME = 'Log purge (nightly)';
    public static final String CRON_DAILY_2AM = '0 0 2 * * ?';
    public static final Integer DEFAULT_RETENTION_DAYS = 30;
    public static final Integer ERROR_RETENTION_DAYS = 180;
    private static final Integer SYNC_DELETE_LIMIT = 10000;
    private static final Integer BATCH_SIZE = 2000;

    public LogPurgeJob() {
    }

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_DAILY_2AM, new LogPurgeJob());
    }

    // ---------- Schedulable ----------

    public void execute(SchedulableContext sc) {
        Datetime now = System.now();
        Datetime defaultCutoff = now.addDays(-DEFAULT_RETENTION_DAYS);
        Datetime errorCutoff = now.addDays(-ERROR_RETENTION_DAYS);

        List<FB_Integration_Log__c> expired = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :defaultCutoff AND (Level__c = null OR Level__c != 'ERROR'))
               OR CreatedDate < :errorCutoff
            LIMIT :SYNC_DELETE_LIMIT
        ];

        if (!expired.isEmpty()) {
            delete expired;
        }

        // A full chunk means there may be more expired logs: purge the remainder in a batch.
        if (expired.size() >= SYNC_DELETE_LIMIT) {
            Database.executeBatch(new LogPurgeJob(), BATCH_SIZE);
        }
    }

    // ---------- Batchable ----------

    public Database.QueryLocator start(Database.BatchableContext bc) {
        Datetime now = System.now();
        Datetime defaultCutoff = now.addDays(-DEFAULT_RETENTION_DAYS);
        Datetime errorCutoff = now.addDays(-ERROR_RETENTION_DAYS);
        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :defaultCutoff AND (Level__c = null OR Level__c != 'ERROR'))
               OR CreatedDate < :errorCutoff
        ]);
    }

    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }
        Database.delete(scope, false);
    }

    public void finish(Database.BatchableContext bc) {
    }
}
