```apex
public with sharing class PipelineSummary {

    private static final List<String> STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        if (fromDate == null || toDate == null) {
            throw new IllegalArgumentException('fromDate and toDate are required.');
        }

        // Every stage is present up front, so stages with no matching
        // opportunities (or only null amounts) map to 0, never null.
        Map<String, Decimal> totals = new Map<String, Decimal>();
        for (String stage : STAGES) {
            totals.put(stage, 0);
        }

        // One aggregate query for all four stages.
        List<AggregateResult> results = [
            SELECT StageName stage, SUM(Amount) total
            FROM Opportunity
            WHERE StageName IN :STAGES
            AND CloseDate >= :fromDate
            AND CloseDate <= :toDate
            WITH USER_MODE
            GROUP BY StageName
        ];

        for (AggregateResult ar : results) {
            String stage = (String) ar.get('stage');
            Decimal total = (Decimal) ar.get('total');
            if (total != null && totals.containsKey(stage)) {
                totals.put(stage, total);
            }
        }

        return totals;
    }
}
