public with sharing class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one NPSP Data Import record per gift, remembering the input position.
        List<npsp__DataImport__c> staged = new List<npsp__DataImport__c>();
        List<Integer> stagedIndexes = new List<Integer>();

        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            ImportResult res = new ImportResult();
            res.success = false;
            results.add(res);

            if (gift == null) {
                res.errorMessage = 'Gift was null and could not be staged.';
                continue;
            }

            staged.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = gift.firstName,
                npsp__Contact1_Lastname__c = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c = gift.amount,
                npsp__Donation_Date__c = gift.giftDate,
                npsp__Donation_Donor__c = 'Contact1'
            ));
            stagedIndexes.add(i);
        }

        if (staged.isEmpty()) {
            return results;
        }

        // Insert the staging records; a staging failure must not stop the others.
        List<Database.SaveResult> saveResults = Database.insert(staged, false);

        List<npsp__DataImport__c> toProcess = new List<npsp__DataImport__c>();
        Map<Id, Integer> indexByDataImportId = new Map<Id, Integer>();

        for (Integer j = 0; j < staged.size(); j++) {
            Integer originalIndex = stagedIndexes[j];
            Database.SaveResult sr = saveResults[j];
            if (sr.isSuccess()) {
                toProcess.add(staged[j]);
                indexByDataImportId.put(staged[j].Id, originalIndex);
            } else {
                List<String> msgs = new List<String>();
                for (Database.Error err : sr.getErrors()) {
                    msgs.add(err.getMessage());
                }
                results[originalIndex].errorMessage =
                    'Could not stage Data Import record: ' + String.join(msgs, '; ');
            }
        }

        if (toProcess.isEmpty()) {
            return results;
        }

        // Process synchronously, in this transaction, with NPSP's BDI Apex API
        // and the org's Data Import settings.
        try {
            npsp__Data_Import_Settings__c diSettings = getDataImportSettings();
            npsp.BDI_DataImport_API.processDataImportRecords(diSettings, toProcess, false);
        } catch (Exception e) {
            for (Integer idx : indexByDataImportId.values()) {
                results[idx].errorMessage = 'Data import processing failed: ' + e.getMessage();
            }
            return results;
        }

        // Build results from the processed Data Import records (re-queried for NPSP's write-back).
        List<npsp__DataImport__c> processed = [
            SELECT Id, npsp__Status__c, npsp__Contact1Imported__c,
                   npsp__DonationImported__c, npsp__FailureInformation__c
            FROM npsp__DataImport__c
            WHERE Id IN :indexByDataImportId.keySet()
        ];

        for (npsp__DataImport__c di : processed) {
            Integer idx = indexByDataImportId.get(di.Id);
            ImportResult res = results[idx];
            res.success = (di.npsp__Status__c == 'Imported');
            res.contactId = di.npsp__Contact1Imported__c;
            res.opportunityId = di.npsp__DonationImported__c;
            if (res.success) {
                res.errorMessage = null;
            } else {
                res.errorMessage = String.isNotBlank(di.npsp__FailureInformation__c)
                    ? di.npsp__FailureInformation__c
                    : 'NPSP did not import this row (status: ' + di.npsp__Status__c + ').';
            }
        }

        return results;
    }

    // The org's Data Import settings (hierarchy custom setting). If the org has no saved
    // settings record yet, fall back to NPSP's defaults: match contacts on first name,
    // last name and email, and never match existing donations.
    private static npsp__Data_Import_Settings__c getDataImportSettings() {
        npsp__Data_Import_Settings__c settings = npsp__Data_Import_Settings__c.getOrgDefaults();
        if (settings.Id == null) {
            if (String.isBlank(settings.npsp__Contact_Matching_Rule__c)) {
                settings.npsp__Contact_Matching_Rule__c = 'Firstname,Lastname,Email';
            }
            if (String.isBlank(settings.npsp__Donation_Matching_Behavior__c)) {
                settings.npsp__Donation_Matching_Behavior__c = 'Do Not Match';
            }
        }
        return settings;
    }
}
